package org.example.backend.controller;
import org.example.backend.service.*;
import org.example.backend.entity.*;
import org.example.backend.security.JwtAuthenticationFilter;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class PlatformEndpointBehaviorTest {
    @Test void iotReadRoutesBindLabDeviceAndQueryIdentities() throws Exception{IotHardwareService hardware=mock(IotHardwareService.class);IotDeviceService devices=mock(IotDeviceService.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new IotHardwareController(hardware,devices)).build();when(devices.listDevices(anyMap())).thenReturn(Map.of("records",List.of(Map.of("id",7))));mvc.perform(get("/iot/devices").param("labId","1").param("deviceType","light")).andExpect(jsonPath("$.data.records[0].id").value(7));verify(devices).listDevices(Map.of("labId","1","deviceType","light"));for(String path:List.of("/iot/hardware","/iot/hardware/devices","/iot/labs/1/devices","/iot/labs/1/overview","/iot/labs/1/status","/iot/labs/1/camera","/iot/devices/LIGHT1/status","/iot/command-logs","/iot/environment/1"))mvc.perform(get(path)).andExpect(status().isOk()).andExpect(jsonPath("$.code").value(200));verify(hardware).getLabStatus(1L);verify(hardware).getDeviceStatus("LIGHT1");verify(devices).getEnvironment(1L);}
    @Test void iotCommandsDefaultOptionalBodiesAndSnapshotsDisableCaching() throws Exception{IotHardwareService hardware=mock(IotHardwareService.class);IotDeviceService devices=mock(IotDeviceService.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new IotHardwareController(hardware,devices)).build();mvc.perform(post("/iot/labs/1/access")).andExpect(status().isOk());verify(hardware).executeAccessCommand(1L,"open",Map.of());mvc.perform(post("/iot/labs/1/access").contentType(MediaType.APPLICATION_JSON).content("{\"action\":\"close\",\"payload\":{\"reason\":\"课程结束\"}}" )).andExpect(status().isOk());verify(hardware).executeAccessCommand(1L,"close",Map.of("reason","课程结束"));mvc.perform(post("/iot/control")).andExpect(status().isOk());verify(devices).control(Map.of());mvc.perform(post("/iot/devices")).andExpect(status().isOk());verify(devices).createDevice(Map.of());mvc.perform(put("/iot/devices/7").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"灯\"}" )).andExpect(status().isOk());verify(devices).updateDevice(7L,Map.of("name","灯"));mvc.perform(delete("/iot/devices/7")).andExpect(status().isOk());verify(devices).deleteDevice(7L);mvc.perform(post("/iot/devices/LIGHT1/commands/on")).andExpect(status().isOk());verify(hardware).executeDeviceCommand("LIGHT1","on",Map.of());when(hardware.getCameraSnapshot("CAM1")).thenReturn(new IotHardwareService.CameraSnapshot(new byte[]{1,2},null));mvc.perform(get("/iot/cameras/CAM1/snapshot")).andExpect(content().bytes(new byte[]{1,2})).andExpect(header().string("Content-Type","image/jpeg")).andExpect(header().string("Cache-Control","no-store"));}
    @Test void noticeRoutesCarryAuthenticatedRecipientIdentityAndExplicitLifecycleActions() throws Exception{NoticeService service=mock(NoticeService.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new NoticeController(service)).build();NoticeEntity notice=new NoticeEntity();notice.setTitle("通知");when(service.createNotice(any())).thenAnswer(call->call.getArgument(0));when(service.updateNotice(eq(7L),any())).thenAnswer(call->call.getArgument(1));mvc.perform(post("/notices").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"通知\"}" )).andExpect(jsonPath("$.data.title").value("通知"));mvc.perform(put("/notices/7").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"更新\"}" )).andExpect(jsonPath("$.data.title").value("更新"));for(String path:List.of("/notices/user","/notices/user/unread","/notices/stats"))mvc.perform(get(path).requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7).requestAttr(JwtAuthenticationFilter.AUTH_ROLE_ATTRIBUTE,"labAdmin")).andExpect(status().isOk());verify(service).listUserNotices(7,"labAdmin",null);verify(service).listUserNotices(7,"labAdmin","未读");verify(service).getNoticeStats(7,"labAdmin");mvc.perform(post("/notices/9/read").requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7).requestAttr(JwtAuthenticationFilter.AUTH_ROLE_ATTRIBUTE,"labAdmin")).andExpect(status().isOk());verify(service).markRead(9L,7,"labAdmin");for(String action:List.of("publish","withdraw","archive"))mvc.perform(post("/notices/9/"+action)).andExpect(status().isOk());verify(service).publishNotice(9L);verify(service).withdrawNotice(9L);verify(service).archiveNotice(9L);mvc.perform(get("/notices/9/recipients")).andExpect(status().isOk());mvc.perform(delete("/notices/9")).andExpect(status().isOk());mvc.perform(post("/notices/business-reminders/sync")).andExpect(status().isOk());mvc.perform(put("/notices/batch").contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isOk());mvc.perform(post("/notices/reset")).andExpect(status().isOk());mvc.perform(get("/notices")).andExpect(status().isOk());verify(service).replaceNotices(List.of());verify(service).deleteNotice(9L);}
    @Test void labMutationsAndResetKeepAuthenticatedManagerScope() throws Exception{LabService labs=mock(LabService.class);DevicesService devices=mock(DevicesService.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new LabController(labs,devices)).build();when(labs.addLab(any())).thenAnswer(call->call.getArgument(0));mvc.perform(post("/labs").contentType(MediaType.APPLICATION_JSON).content("{\"labName\":\"机房\"}" )).andExpect(jsonPath("$.data.labName").value("机房"));mvc.perform(put("/labs/1").contentType(MediaType.APPLICATION_JSON).content("{\"labName\":\"更新\"}" )).andExpect(status().isOk());verify(labs).updateLab(eq(1),argThat(lab->"更新".equals(lab.getLabName())));mvc.perform(put("/labs/batch").contentType(MediaType.APPLICATION_JSON).content("{\"resource\":\"labs\",\"records\":[{\"id\":1}]}" )).andExpect(status().isOk());verify(labs).updateLabs(argThat(rows->rows.size()==1&&rows.get(0).getId()==1));mvc.perform(get("/labs/1/devices")).andExpect(status().isOk());verify(devices).getDevicesByLabId(1);mvc.perform(delete("/labs/1")).andExpect(status().isOk());verify(labs).deleteLab(1);mvc.perform(post("/labs/reset").requestAttr(JwtAuthenticationFilter.AUTH_ROLE_ATTRIBUTE,"labAdmin").requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7)).andExpect(status().isOk());verify(labs).getLabs(7);mvc.perform(post("/labs/reset").requestAttr(JwtAuthenticationFilter.AUTH_ROLE_ATTRIBUTE,"systemAdmin")).andExpect(status().isOk());verify(labs).getLabs((Integer)null);}
    @Test void modulePathAndRecordsAreForwardedWithoutConfusingResourceField() throws Exception{ModuleRecordService modules=mock(ModuleRecordService.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new ModuleRecordController(modules)).build();when(modules.listModuleRecords("sample")).thenReturn(List.of(Map.of("id",1)));when(modules.replaceModuleRecords(eq("sample"),anyList())).thenAnswer(call->call.getArgument(1));mvc.perform(get("/modules/sample")).andExpect(jsonPath("$.data[0].id").value(1));mvc.perform(put("/modules/sample/batch").contentType(MediaType.APPLICATION_JSON).content("{\"resource\":\"wrong\",\"records\":[{\"id\":2}]}" )).andExpect(jsonPath("$.data[0].id").value(2));verify(modules).replaceModuleRecords("sample",List.of(Map.of("id",2)));mvc.perform(post("/modules/sample/reset")).andExpect(status().isOk());verify(modules).resetModuleRecords("sample");}
    @Test void aiConfigBuildsSecureWebsocketUrlAndChatFiltersHistoryPayloads() throws Exception{TongyiAgentService tongyi=mock(TongyiAgentService.class);AiAssistantUserConfigService config=mock(AiAssistantUserConfigService.class);AiPlatformChatService chat=mock(AiPlatformChatService.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new AiAssistantConfigController(tongyi,config,chat)).build();mvc.perform(get("/ai-assistant/config").secure(true).with(request->{request.setScheme("https");request.setServerName("school.test");request.setServerPort(443);return request;})).andExpect(jsonPath("$.data.ws_url").value("wss://school.test:443/ai-assistant/ws"));mvc.perform(get("/config")).andExpect(jsonPath("$.data.ws_url").value("ws://localhost:80/ai-assistant/ws"));mvc.perform(get("/ai-assistant/user-config").requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7)).andExpect(status().isOk());verify(config).getConfig(7);mvc.perform(put("/ai-assistant/user-config").requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7).contentType(MediaType.APPLICATION_JSON).content("{\"enabled\":true}" )).andExpect(status().isOk());verify(config).saveConfig(7,Map.of("enabled",true));mvc.perform(post("/ai-assistant/user-config/test").requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7)).andExpect(status().isOk());verify(config).testConnection(7,null);mvc.perform(post("/ai-assistant/chat").requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7).contentType(MediaType.APPLICATION_JSON).content("{\"question\":\"状态\",\"conversationId\":\"c1\",\"history\":[{\"role\":\"user\",\"content\":\"旧问题\"},42]}" )).andExpect(status().isOk());verify(chat).chat(eq(7),eq("状态"),eq(List.of(Map.of("role","user","content","旧问题"))),eq("c1"),any());}
}
